CREATE TABLE IF NOT EXISTS campus_merchant_category(code VARCHAR(20) PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO campus_merchant_category(code,name) VALUES('CATERING','餐饮'),('RETAIL','零售'),('SERVICE','服务'),('OTHER','其他'),('SYSTEM','系统测试');
CREATE TABLE IF NOT EXISTS campus_merchant_extra(merchant_id BIGINT PRIMARY KEY,owner_name VARCHAR(50) NOT NULL DEFAULT '',owner_phone VARCHAR(30) NOT NULL DEFAULT '',license_no VARCHAR(100) NOT NULL DEFAULT '',permit_no VARCHAR(100) NOT NULL DEFAULT '',permit_expiry DATE NULL,introduction VARCHAR(2000) NOT NULL DEFAULT '',license_image VARCHAR(36) NULL,permit_image VARCHAR(36) NULL,merchant_image VARCHAR(36) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS campus_merchant_image(id VARCHAR(36) PRIMARY KEY,mime VARCHAR(30) NOT NULL,content MEDIUMBLOB NOT NULL,actor_id BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
